# Common classes and definitions for DIPC messages.
#
# Modules generated by didlpygen from .didl files contain only their
# own structs, messages and protocols, and build on the classes here.
#
# Wire format:
# - Fields are little-endian, at the offsets given in the IR.
# - Every message starts with the header: uint32 txid, uint16 flags,
#   and uint16 method number.  The only flag is ERROR, set on an error
#   reply (see ErrorReply); the others are reserved, and must be 0.
# - The message body follows the header, aligned to the body's
#   alignment.
# - An 'opaque' field is a sequence of bytes, encoded as a descriptor:
#   uint32 offset of its value from the start of the message, then
#   uint32 length.  The values are appended to the message, after the
#   fixed part: each starts on an 8-byte boundary, and is padded to a
#   multiple of 8 bytes.
# - A 'string' field is encoded as an opaque, holding UTF-8.  Decoding
#   a value that isn't valid UTF-8 fails.
# - A 'sequence<T>' field is a descriptor: uint32 offset of an array of
#   elements, then uint32 count of elements.  The array is a value, like
#   an opaque's, holding each element's fixed part, at a stride of T's
#   size.  Out-of-line values of the elements (their strings, opaques
#   and sequences) follow the array, in element order.
# - Values are appended in the order they're encoded: fields in order,
#   and a sequence's array before its elements' values.  Decoding
#   requires exactly that order, with no gaps or overlaps, so a message
#   can't refer to one value many times.
# - A 'port' field is a uint16 index into the list of handles
#   transferred with the message, or NO_PORT.  encode() returns the
#   list along with the bytes, and decode() takes it back.
# - An enum field is encoded as its base integer type.  Decoding a value
#   that isn't one of the enum's members fails.


import struct
import typing
from enum import IntEnum

from .errors import MessageDecodingError


# Control exports
__all__ = [
    "BYTE_ORDER",
    "Codec",
    "Decoder",
    "ERROR",
    "Encoder",
    "EnumCodec",
    "ErrorCode",
    "ErrorReply",
    "HEADER_FORMAT",
    "HEADER_LENGTH",
    "Message",
    "NO_PORT",
    "OPAQUE_CODEC",
    "OpaqueCodec",
    "PORT_CODEC",
    "PortCodec",
    "Record",
    "STRING_CODEC",
    "ScalarCodec",
    "SequenceCodec",
    "StringCodec",
    "StructCodec",
    "decode_flags",
    "decode_method",
    "decode_txid",
]


# struct module byte order prefix: little-endian, standard sizes, no alignment.
BYTE_ORDER = "<"

# Message header: txid, flags, method.
HEADER_FORMAT = BYTE_ORDER + "IHH"
HEADER_LENGTH = 8

# Header flag: the message is an error reply.
ERROR = 0x0001

# Port index meaning "no port".
NO_PORT = 0xFFFF


def decode_txid(buffer: bytes) -> int:
    """Decode the transaction identifier from a message buffer."""
    if len(buffer) < HEADER_LENGTH:
        raise MessageDecodingError("buffer too short for header")
    return struct.unpack_from(HEADER_FORMAT, buffer)[0]


def decode_flags(buffer: bytes) -> int:
    """Decode the header flags from a message buffer."""
    if len(buffer) < HEADER_LENGTH:
        raise MessageDecodingError("buffer too short for header")
    return struct.unpack_from(HEADER_FORMAT, buffer)[1]


def decode_method(buffer: bytes) -> int:
    """Decode the method number from a message buffer."""
    if len(buffer) < HEADER_LENGTH:
        raise MessageDecodingError("buffer too short for header")
    return struct.unpack_from(HEADER_FORMAT, buffer)[2]


class Record:
    """Base class for structs and messages: compared and shown by value."""

    # A struct's codec, set by the generated module when the struct is
    # used in a sequence.
    CODEC: "typing.ClassVar[StructCodec]"

    def __eq__(self, other) -> bool:
        return type(other) is type(self) and vars(other) == vars(self)

    def __repr__(self) -> str:
        fields = ", ".join(f"{name}={value!r}" for name, value in vars(self).items())
        return f"{type(self).__name__}({fields})"


class Message(Record):
    """Common header for all messages."""

    # Method number, set by each message class.
    METHOD = 0

    # Header flags, set by each message class.
    FLAGS = 0

    # For a request, its response class; None for a one-way message.
    RESPONSE: "type[Message] | None" = None

    def __init__(self, txid: int = 0):
        """Constructor."""

        # Transaction identifier; 0 for one-way messages.
        self.txid = txid

    def encode(self) -> tuple[bytes, list[int]]:
        """Encode message header to wire format.

        :returns: (bytes, handles to transfer with them)."""
        return struct.pack(HEADER_FORMAT, self.txid, self.FLAGS, self.METHOD), []

    def decode(self, buffer: bytes, handles: typing.Sequence[int] = ()):
        """Decode message header from byte buffer.

        :param handles: Handles transferred with the message."""
        if len(buffer) < HEADER_LENGTH:
            raise MessageDecodingError("buffer too short for header")

        bits = struct.unpack_from(HEADER_FORMAT, buffer)
        if bits[1] != self.FLAGS:
            raise MessageDecodingError(f"flags {bits[1]:#x}, expected {self.FLAGS:#x}")
        if bits[2] != self.METHOD:
            raise MessageDecodingError(f"method {bits[2]}, expected {self.METHOD}")
        self.txid = bits[0]
        return

    @staticmethod
    def encode_port(handles: list[int], handle: int | None) -> int:
        """Return the index for a port field, adding it to the handles.

        A handle already in the list keeps its index."""
        if handle is None:
            return NO_PORT
        if handle not in handles:
            handles.append(handle)
        return handles.index(handle)

    @staticmethod
    def decode_port(handles: typing.Sequence[int], index: int) -> int | None:
        """Return the handle for a port field's index."""
        if index == NO_PORT:
            return None
        if index >= len(handles):
            raise MessageDecodingError(f"port index {index}, but {len(handles)} handles")
        return handles[index]

    @staticmethod
    def decode_enum[E: IntEnum](enum: type[E], value: int) -> E:
        """Return the member of an enum for a field's value."""
        try:
            return enum(value)
        except ValueError:
            raise MessageDecodingError(f"{value} is not a {enum.__name__}") from None

    @staticmethod
    def pad_bytes(raw_bytes: bytes) -> bytes:
        """Pad an opaque value to a multiple of 8 bytes."""
        return raw_bytes + b'\0' * (-len(raw_bytes) % 8)

    @staticmethod
    def decode_opaque(buffer: bytes, start: int, offset: int, length: int) -> bytes:
        """Return the value for an opaque field's descriptor.

        :param start: Offset of the first value in the message."""
        if offset % 8 != 0:
            raise MessageDecodingError(f"opaque value not 8-byte aligned: offset {offset}")
        if offset < start or offset + length > len(buffer):
            raise MessageDecodingError(f"opaque value out of range: offset {offset}, length {length}")
        return bytes(buffer[offset:offset + length])


def _align8(n: int) -> int:
    return (n + 7) // 8 * 8


class Encoder:
    """Appends a message's out-of-line values, after its fixed part.

    Each value starts on an 8-byte boundary, and is padded to a multiple
    of 8 bytes."""

    def __init__(self, start: int, handles: list[int]):
        """Constructor.

        :param start: Offset of the first value in the message.
        :param handles: The message's handles, added to by port fields."""
        self.start = start
        self.handles = handles
        self.data = bytearray()

    def _append(self, value: bytes) -> int:
        offset = self.start + len(self.data)
        self.data += value
        self.data += b'\0' * (-len(value) % 8)
        return offset

    def opaque(self, value: bytes) -> tuple[int, int]:
        """Append an opaque value, and return its descriptor."""
        return self._append(value), len(value)

    def string(self, value: str) -> tuple[int, int]:
        """Append a string value, and return its descriptor."""
        return self.opaque(value.encode("utf-8"))

    def port(self, handle: int | None) -> int:
        """Return the index for a port, adding it to the handles."""
        return Message.encode_port(self.handles, handle)

    def sequence(self, values: typing.Sequence[typing.Any], element: "Codec") -> tuple[int, int]:
        """Append a sequence's array, and its elements' values, and
        return its descriptor."""
        offset = self._append(bytes(len(values) * element.size))
        for n, value in enumerate(values):
            # The element's values are appended before its fixed part is
            # packed into the array.
            element.struct.pack_into(self.data, offset - self.start + n * element.size,
                                     *element.flatten(value, self))
        return offset, len(values)


class Decoder:
    """Reads a message's out-of-line values, checking that they're laid
    out exactly as an Encoder would."""

    def __init__(self, buffer: bytes, start: int, handles: typing.Sequence[int] = ()):
        """Constructor.

        :param start: Offset of the first value in the message.
        :param handles: Handles transferred with the message."""
        self.buffer = buffer
        self.handles = handles
        self.position = start

    def _block(self, what: str, offset: int, length: int) -> int:
        if offset != self.position:
            raise MessageDecodingError(f"{what} value at offset {offset}, expected {self.position}")
        if offset + length > len(self.buffer):
            raise MessageDecodingError(f"{what} value out of range: offset {offset}, length {length}")
        self.position += _align8(length)
        return offset

    def opaque(self, offset: int, length: int) -> bytes:
        """Return the value for an opaque descriptor."""
        self._block("opaque", offset, length)
        return bytes(self.buffer[offset:offset + length])

    def string(self, offset: int, length: int) -> str:
        """Return the value for a string descriptor."""
        self._block("string", offset, length)
        try:
            return bytes(self.buffer[offset:offset + length]).decode("utf-8")
        except UnicodeDecodeError as e:
            raise MessageDecodingError(f"string value is not valid UTF-8: {e.reason}") from None

    def port(self, index: int) -> int | None:
        """Return the handle for a port index."""
        return Message.decode_port(self.handles, index)

    def sequence(self, element: "Codec", offset: int, count: int) -> list[typing.Any]:
        """Return the elements for a sequence descriptor."""
        # Otherwise, a short message could hold a vast count of them.
        if element.size == 0:
            raise MessageDecodingError("sequence elements can't be empty")
        self._block("sequence", offset, count * element.size)
        return [element.unflatten(iter(element.struct.unpack_from(self.buffer, offset + n * element.size)), self)
                for n in range(count)]


class Codec:
    """How a sequence's elements are encoded: the format of each one's
    fixed part, and how it's converted to and from the values packed in
    that format.

    This one is for numbers and bools."""

    def __init__(self, format: str):
        """Constructor.

        :param format: struct module format, without byte order."""
        self.format = format
        self.struct = struct.Struct(BYTE_ORDER + format)
        self.size = self.struct.size

    def flatten(self, value: typing.Any, out: Encoder) -> tuple[typing.Any, ...]:
        """Return the values to pack for an element."""
        return (value,)

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        """Return an element, from the values unpacked for it."""
        return next(bits)


ScalarCodec = Codec


class EnumCodec(Codec):
    def __init__(self, enum: type[IntEnum], format: str):
        super().__init__(format)
        self.enum = enum

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        return Message.decode_enum(self.enum, next(bits))


class PortCodec(Codec):
    def __init__(self):
        super().__init__("H")

    def flatten(self, value: typing.Any, out: Encoder) -> tuple[typing.Any, ...]:
        return (out.port(value),)

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        return inp.port(next(bits))


class OpaqueCodec(Codec):
    def __init__(self):
        super().__init__("II")

    def flatten(self, value: typing.Any, out: Encoder) -> tuple[typing.Any, ...]:
        return out.opaque(value)

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        return inp.opaque(next(bits), next(bits))


class StringCodec(Codec):
    def __init__(self):
        super().__init__("II")

    def flatten(self, value: typing.Any, out: Encoder) -> tuple[typing.Any, ...]:
        return out.string(value)

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        return inp.string(next(bits), next(bits))


class SequenceCodec(Codec):
    def __init__(self, element: Codec):
        super().__init__("II")
        self.element = element

    def flatten(self, value: typing.Any, out: Encoder) -> tuple[typing.Any, ...]:
        return out.sequence(value, self.element)

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        return inp.sequence(self.element, next(bits), next(bits))


class StructCodec(Codec):
    """A struct: its fields' codecs, at their offsets, padded to its size."""

    def __init__(self, cls: type[Record], size: int, fields: list[tuple[str, int, Codec]]):
        format = ""
        position = 0
        for _, offset, codec in fields:
            if offset > position:
                format += f"{offset - position}x"
            format += codec.format
            position = offset + codec.size
        if size > position:
            format += f"{size - position}x"
        super().__init__(format)
        self.cls = cls
        self.fields = fields

    def flatten(self, value: typing.Any, out: Encoder) -> tuple[typing.Any, ...]:
        bits: list[typing.Any] = []
        for name, _, codec in self.fields:
            bits.extend(codec.flatten(getattr(value, name), out))
        return tuple(bits)

    def unflatten(self, bits: typing.Iterator[typing.Any], inp: Decoder) -> typing.Any:
        value = self.cls()
        for name, _, codec in self.fields:
            setattr(value, name, codec.unflatten(bits, inp))
        return value


PORT_CODEC = PortCodec()
OPAQUE_CODEC = OpaqueCodec()
STRING_CODEC = StringCodec()


class ErrorCode(IntEnum):
    """Error reply codes."""

    # The service has no such method.
    UNKNOWN_METHOD = 1

    # The request couldn't be decoded.
    BAD_MESSAGE = 2

    # The service doesn't implement the method.
    NOT_IMPLEMENTED = 3

    # The service failed while handling the request.
    INTERNAL_ERROR = 4


class ErrorReply(Message):
    """Reply to a request that failed, in place of its response.

    It has the request's txid and method, and the ERROR flag set.  Its
    body is a uint32 code (see ErrorCode), and an opaque UTF-8
    description."""

    FLAGS = ERROR
    BODY_FORMAT = BYTE_ORDER + "III"
    BODY_START = HEADER_LENGTH
    LENGTH = 20
    DATA_START = 24

    def __init__(self, txid: int = 0, method: int = 0, code: int = 0, description: str = ""):
        super().__init__(txid)
        self.METHOD = method
        self.code = code
        self.description = description

    def encode(self) -> tuple[bytes, list[int]]:
        buf, handles = super().encode()
        description = self.description.encode("utf-8", errors="replace")
        buf += struct.pack(self.BODY_FORMAT, self.code, self.DATA_START, len(description))
        buf += b'\0' * (self.DATA_START - self.LENGTH)
        buf += self.pad_bytes(description)
        return buf, handles

    def decode(self, buffer: bytes, handles: typing.Sequence[int] = ()):
        # Any method: it's the request's.
        if len(buffer) >= HEADER_LENGTH:
            self.METHOD = decode_method(buffer)
        super().decode(buffer, handles)
        if len(buffer) < self.LENGTH:
            raise MessageDecodingError("buffer too short for message")

        bits = struct.unpack_from(self.BODY_FORMAT, buffer, self.BODY_START)
        self.code = bits[0]
        description = self.decode_opaque(buffer, self.DATA_START, bits[1], bits[2])
        self.description = description.decode("utf-8", errors="replace")
        return
